@import "@fontsource-variable/manrope";

/* Light: warm paper, white cards, blue-green ink, a deep teal brand and pale mint fills.
   chart-2…5 are the soft clouds behind the panels (sky, peach, honey, mint). */
:root {
  --background: oklch(0.984 0.004 95);
  --foreground: oklch(0.225 0.008 220);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.225 0.008 220);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.225 0.008 220);
  --primary: oklch(0.225 0.008 220);
  --primary-foreground: oklch(0.984 0.004 95);
  --secondary: oklch(0.958 0.006 95);
  --secondary-foreground: oklch(0.225 0.008 220);
  --muted: oklch(0.955 0.006 95);
  --muted-foreground: oklch(0.44 0.01 220);
  --accent: oklch(0.94 0.03 175);
  --accent-foreground: oklch(0.4 0.075 180);
  --destructive: oklch(0.58 0.2 27);
  --destructive-foreground: oklch(0.984 0.004 95);
  --border: oklch(0.905 0.008 90);
  --input: oklch(0.87 0.008 90);
  --ring: oklch(0.47 0.085 180);
  --highlight: oklch(0.47 0.085 180);
  --highlight-foreground: oklch(0.984 0.004 95);
  --glow: oklch(0.86 0.07 172);
  --chart-1: oklch(0.47 0.085 180);
  --chart-2: oklch(0.9 0.035 240);
  --chart-3: oklch(0.93 0.05 65);
  --chart-4: oklch(0.93 0.07 95);
  --chart-5: oklch(0.76 0.09 178);
  --sidebar: oklch(0.975 0.005 95);
  --sidebar-foreground: oklch(0.225 0.008 220);
  --sidebar-primary: oklch(0.47 0.085 180);
  --sidebar-primary-foreground: oklch(0.984 0.004 95);
  --sidebar-accent: oklch(0.94 0.03 175);
  --sidebar-accent-foreground: oklch(0.4 0.075 180);
  --sidebar-border: oklch(0.905 0.008 90);
  --sidebar-ring: oklch(0.47 0.085 180);

  --typeface-body: "Manrope Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Manrope Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1.25rem;
  --page-width: 72rem;
  --page-gutter: 1.5rem;
  --section-y: 7rem;
}

/* Dark: the almost-black green of the fluted bands, glass cards, paper text and CTAs,
   bright mint for eyebrows and PRO badges, a teal glow. */
.dark {
  --background: oklch(0.17 0.018 185);
  --foreground: oklch(0.984 0.004 95);
  --card: oklch(0.22 0.022 185);
  --card-foreground: oklch(0.984 0.004 95);
  --popover: oklch(0.21 0.02 185);
  --popover-foreground: oklch(0.984 0.004 95);
  --primary: oklch(0.984 0.004 95);
  --primary-foreground: oklch(0.225 0.008 220);
  --secondary: oklch(0.25 0.022 185);
  --secondary-foreground: oklch(0.984 0.004 95);
  --muted: oklch(0.25 0.02 185);
  --muted-foreground: oklch(0.79 0.012 200);
  --accent: oklch(0.93 0.035 175);
  --accent-foreground: oklch(0.3 0.05 182);
  --destructive: oklch(0.68 0.19 25);
  --destructive-foreground: oklch(0.984 0.004 95);
  --border: oklch(1 0 0 / 12%);
  --input: oklch(1 0 0 / 16%);
  --ring: oklch(0.76 0.09 178);
  --highlight: oklch(0.78 0.09 178);
  --highlight-foreground: oklch(0.22 0.04 185);
  --glow: oklch(0.55 0.09 180);
  --chart-1: oklch(0.58 0.115 180);
  --chart-2: oklch(0.8 0.07 220);
  --chart-3: oklch(0.6 0.08 60);
  --chart-4: oklch(0.88 0.11 95);
  --chart-5: oklch(0.7 0.09 178);
  --sidebar: oklch(0.19 0.02 185);
  --sidebar-foreground: oklch(0.984 0.004 95);
  --sidebar-primary: oklch(0.78 0.09 178);
  --sidebar-primary-foreground: oklch(0.22 0.04 185);
  --sidebar-accent: oklch(0.25 0.022 185);
  --sidebar-accent-foreground: oklch(0.984 0.004 95);
  --sidebar-border: oklch(1 0 0 / 12%);
  --sidebar-ring: oklch(0.76 0.09 178);
}
